public int[] merge(int[] left, int[] right) {
    int[] result = new int[left.length + right.length];
    int i = 0;
    int j = 0;
    int k = 0;
    while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) {
            result[k++] = left[i++];
        } else {
            result[k++] = right[j++];
        }
    }
    while (i < left.length) {
        result[k++] = left[i++];
    }
    while (j < right.length) {
        result[k++] = right[j++];
    }
    return result;
}

Java.Functions:
public int[] mergeSortedArrays(int[] left, int[] right) {
    return merge(left, right);
}

private int[] merge(int[] left, int[] right) {
    int[] result = new int[left.length + right.length];
    int i = 0;
    int j = 0;
    int k = 0;
    while (i < left.length && j < right.length) {
        result[k++] = left[i] <= right[j] ? left[i++] : right[j++];
    }
    while (i < left.length) {
        result[k++] = left[i++];
    }
    while (j < right.length) {
        result[k++] = right[j++];
    }
    return result;
}

Java.Recursion:
public int[] mergeRecursive(int[] left, int[] right) {
    int[] result = new int[left.length + right.length];
    mergeRecursive(left, right, 0, 0, 0, result);
    return result;
}

private void mergeRecursive(int[] left, int[] right, int i, int j, int k, int[] result) {
    if (i == left.length) {
        while (j < right.length) {
            result[k++] = right[j++];
        }
        return;
    }
    if (j == right.length) {
        while (i < left.length) {
            result[k++] = left[i++];
        }
        return;
    }
    if (left[i] <= right[j]) {
        result[k] = left[i];
        mergeRecursive(left, right, i + 1, j, k + 1, result);
    } else {
        result[k] = right[j];
        mergeRecursive(left, right, i, j + 1, k + 1, result);
    }
}
